$bb=$db->query('SELECT * FROM '.$p.'asaas_company_accounts WHERE id=?',[$accounts[$b]])->row();
$body=fn($id,$remote='auth_same')=>json_encode(['id'=>$id,'event'=>'PIX_AUTOMATIC_RECURRING_AUTHORIZATION_ACTIVATED','authorization'=>['id'=>$remote,'payload'=>'private-qr','customer'=>'private-customer']]);
