essentialCheck($asaas->receive($aa->webhook_public_id,['Content-Type'=>'application/json','asaas-access-token'=>str_repeat('z',64)],$body('bad'))['status']===401,'invalid token rejected before inbox');
essentialCheck($asaas->receive($aa->webhook_public_id,$headers,$body('same'))['status']===200,'authenticated event queued');
