essentialCheck($asaas->receive($bb->webhook_public_id,$headers,$body('same'))['status']===200,'same event and resource IDs isolated by account');
$event=$eventId('same',$aa->id);$calls=[];$during=null;
$transport=function($env,$method,$path,$payload,$secret)use(&$calls,&$during,$aa,$db){essentialCheck(!$db->pdo->inTransaction(),'HTTP outside owned transaction');essentialCheck($method==='GET'&&$payload===null&&$env==='sandbox','only scoped read-only HTTP');$calls[]=$path;if($path==='wallets/')return ['data'=>[['id'=>$aa->account_id]],'hasMore'=>false];if($during)$during();return ['id'=>'auth_same','status'=>'ACTIVE','frequency'=>'MONTHLY','payload'=>'private-qr'];};
