essentialCheck($asaas->receive($aa->webhook_public_id,$headers,$body('same','other'))['status']===409,'conflicting repeated event quarantined');
essentialCheck($asaas->receive($aa->webhook_public_id,$headers,$body('same'))['status']===409,'conflict cannot be erased by replay');
$asaas->receive($aa->webhook_public_id,$headers,$body('revoke'));$revoke=$eventId('revoke',$aa->id);
