essentialCheck($inbox->process($a,7,$revoke,$aa->revision,$revokingDecrypt,$transport)['state']==='review_required'&&count($calls)===$n,'revocation during decryption prevents even wallet HTTP');$db->query('UPDATE '.$p.'asaas_company_accounts SET enabled=1 WHERE id=?',[$aa->id]);
$asaas->receive($aa->webhook_public_id,$headers,$body('timeout'));$timeout=$eventId('timeout',$aa->id);
$fail=function(){throw new RuntimeException('private-provider-error');};
for($i=1;$i<=5;$i++){$result=$inbox->process($a,7,$timeout,$aa->revision,$dec,$fail);essentialCheck($result['state']===($i===5?'review_required':'retry'),'bounded retry '.$i);$db->query('UPDATE '.$p.'asaas_company_pix_event_jobs SET next_attempt=? WHERE event_id=?',['2020-01-01 00:00:00',$timeout]);}
$asaas->receive($aa->webhook_public_id,$headers,$body('worker'));$worker=$eventId('worker',$aa->id);
essentialCheck($inbox->tick($dec,$transport)===[],'workers default disabled; no inferred consent');
$inbox->configure($a,7,$aa->id,$aa->revision,str_repeat('0',64),true);
$states=$inbox->tick($dec,$transport);essentialCheck($states===[['state'=>'observed']],'explicit observation worker processes scoped due event');
$rows=$inbox->page($a,7);essentialCheck(count($rows['workers'])===1&&count($rows['events'])===4,'page includes only current company events and worker');
$asaas->receive($aa->webhook_public_id,$headers,$body('concurrent'));$race=$eventId('concurrent',$aa->id);$nested=null;
$during=function()use(&$nested,$inbox,$a,$race,$aa,$dec,$transport){$nested=$inbox->process($a,7,$race,$aa->revision,$dec,$transport);};
essentialCheck($inbox->process($a,7,$race,$aa->revision,$dec,$transport)['state']==='observed'&&$nested===['state'=>'busy'],'concurrent claimant observes live lease without another GET');$during=null;
$instruction=json_encode(['id'=>'instruction','event'=>'PIX_AUTOMATIC_RECURRING_PAYMENT_INSTRUCTION_SCHEDULED','paymentInstruction'=>['id'=>'ins_same','authorization'=>['id'=>'auth_same'],'paymentId'=>'pay_same']]);
essentialCheck($asaas->receive($aa->webhook_public_id,$headers,$instruction)['status']===200,'instruction identifiers accepted after authentication');$instructionId=$eventId('instruction',$aa->id);
$instructionTransport=function($env,$method,$path,$payload,$secret)use($aa){if($path==='wallets/')return ['data'=>[['id'=>$aa->account_id]],'hasMore'=>false];essentialCheck($path==='pix/automatic/paymentInstructions/ins_same','fixed canonical instruction endpoint');return ['id'=>'ins_same','authorization'=>['id'=>'auth_same'],'paymentId'=>'pay_same','status'=>'DONE','customer'=>'private-customer'];};
essentialCheck($inbox->process($a,7,$instructionId,$aa->revision,$dec,$instructionTransport)['state']==='observed','DONE only creates observation, no financial receipt');
$asaas->receive($aa->webhook_public_id,$headers,str_replace('"instruction"','"wrong_instruction"',$instruction));$wrongId=$eventId('wrong_instruction',$aa->id);
$wrongInstruction=function($env,$method,$path,$payload,$secret)use($instructionTransport){$r=$instructionTransport($env,$method,$path,$payload,$secret);if($path!=='wallets/')$r['authorization']['id']='foreign_authorization';return $r;};
essentialCheck($inbox->process($a,7,$wrongId,$aa->revision,$dec,$wrongInstruction)['state']==='review_required','instruction cannot be transplanted between authorizations');
$asaas->receive($aa->webhook_public_id,$headers,$body('revoked_after_http'));$late=$eventId('revoked_after_http',$aa->id);
$during=function()use($db,$p,$aa){$db->query('UPDATE '.$p.'asaas_company_accounts SET enabled=0 WHERE id=?',[$aa->id]);};
essentialCheck($inbox->process($a,7,$late,$aa->revision,$dec,$transport)['state']==='review_required','revocation after HTTP discards response');$during=null;$db->query('UPDATE '.$p.'asaas_company_accounts SET enabled=1 WHERE id=?',[$aa->id]);
essentialCheck(!$db->query('SELECT id FROM '.$p.'asaas_company_pix_observations WHERE event_id=?',[$late])->row(),'revoked response not persisted');
$asaas->receive($aa->webhook_public_id,$headers,$body('rollback'));$rollback=$eventId('rollback',$aa->id);
$db->failOn='INSERT INTO '.$p.'asaas_company_pix_observations';
essentialCheck($inbox->process($a,7,$rollback,$aa->revision,$dec,$transport)['state']==='retry','failed observation write leaves retryable job');$db->failOn=null;
essentialCheck(!$db->query('SELECT id FROM '.$p.'asaas_company_pix_observations WHERE event_id=?',[$rollback])->row(),'failed transaction leaves no partial evidence');
$db->query('UPDATE '.$p.'asaas_company_pix_event_jobs SET next_attempt=? WHERE event_id=?',['2020-01-01 00:00:00',$rollback]);
essentialCheck($inbox->process($a,7,$rollback,$aa->revision,$dec,$transport)['state']==='observed','retry after storage failure confirms observation');
$all=json_encode($db->query('SELECT * FROM '.$p.'asaas_company_pix_events')->result_array());essentialCheck(!str_contains($all,'private-')&&!str_contains($all,$token),'webhook stores neither payload extras nor credentials');
essentialCheck($before===[$db->query('SELECT COUNT(*) n FROM '.$p.'invoicepaymentrecords')->row()->n,$db->query('SELECT COUNT(*) n FROM '.$p.'asaas_payment_origins')->row()->n],'ACTIVE observations never create origin or receipt');
echo 'Pix inbox: '.($GLOBALS['essentialChecks']-$start).' additional checks, MySQL and simulated provider.'.PHP_EOL;
